import React from 'react';
import { Link } from 'react-router-dom';

const styles = {
  footer: {
    backgroundColor: '#1a202c', 
    color: '#a0aec0',
    padding: '40px 20px', // Increased top/bottom padding
    textAlign: 'center',
    borderTop: '1px solid #2d3748',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  // --- New styles for branding ---
  brandingContainer: {
    marginBottom: '25px',
  },
  clinicName: {
    color: '#e2e8f0', // Brighter white for the name
    fontSize: '1.8rem',
    fontWeight: 'bold',
    margin: '0 0 5px 0',
  },
  tagline: {
    color: '#a0aec0', // Softer color for the tagline
    fontSize: '1rem',
    fontStyle: 'italic',
    margin: 0,
  },
  // --- End of new styles ---
  nav: {
    marginBottom: '25px',
    paddingTop: '25px',
    borderTop: '1px solid #2d3748' // Line separator
  },
  copyright: {
    marginTop: '16px',
    fontSize: '0.9rem',
    color: '#a0aec0',
  }
};

// CSS for link styles and hover effects for better performance
const dynamicStyles = `
  .footer-link {
    color: #e2e8f0;
    text-decoration: none;
    margin: 0 15px;
    font-size: 1rem;
    transition: color 0.3s ease;
  }

  .footer-link:hover {
    color: #a7ffeb; /* Highlight color on hover */
  }
`;

const Footer = () => {
  // Array of footer links remains the same
  const footerLinks = [
    { text: 'Home', path: '/', isRouterLink: true },
    { text: 'About Us', path: '/about', isRouterLink: true },
    { text: 'Services', path: '/#services', isRouterLink: false },
    { text: 'Contact Us', path: '/#contact', isRouterLink: false },
    { text: 'Terms and Conditions', path: '/terms', isRouterLink: true },
  ];

  return (
    <>
      {/* This injects the link hover styles into the document */}
      <style>{dynamicStyles}</style>

      <footer style={styles.footer}>
        <div style={styles.container}>

          {/* --- New branding section --- */}
          <div style={styles.brandingContainer}>
            <h2 style={styles.clinicName}>Karpagam Clinic</h2>
            <p style={styles.tagline}>Your Health, Our Priority</p>
          </div>
          
          <nav style={styles.nav}>
            {footerLinks.map(({ text, path, isRouterLink }) => 
              isRouterLink ? (
                <Link
                  key={text}
                  to={path}
                  className="footer-link" // Use className for styling
                >
                  {text}
                </Link>
              ) : (
                <a
                  key={text}
                  href={path}
                  className="footer-link" // Use className for styling
                >
                  {text}
                </a>
              )
            )}
          </nav>
          
          <p style={styles.copyright}>
            &copy; {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
          </p>
        </div>
      </footer>
    </>
  );
};

export default Footer;
